def _build():  # PROBLEMS from the artifacts; run from the repository root
    rows = json.load(open(DATA["rows"]))
    text = {p["index"]: p for p in json.load(open(DATA["problems"]))}
    cut = lambda s, n: s if len(s) <= n else s[:n - 1].rstrip() + "…"
    kind = lambda right, cap: "r" if right else "c" if cap else "w"
    out = []
    for r in rows:
        i = r["problem_index"]
        assert r["t1_start"].startswith(DATA["cue_text"]), i
        out.append([i, cut(text[i]["problem"], 240), text[i]["answer"], kind(r["t3_right"], r["t3_cap_hit"]),
                    kind(r["t1_right"], r["t1_cap_hit"]), (r["t3_extracted_v3"] or "")[:40], (r["t1_extracted_v3"] or "")[:40],
                    r["t3_start"][:170], r["t1_start"][len(DATA["cue_text"]):][:150]])
    return out


# The icon of this finding's tile on /findings (tools/findings.py says how it is called): the page's own picture,
# reduced. A glass slab with three lines of an answer on it; the start of the first line, the cue, is lit.
ICON = r"""(kit, t, tilt) => {
  const a = 44, b = 38, th = 5, top = th / 2, at = (u, v) => kit.at(a * u, b * v, top);
  return kit.slab(a, b, th) +
    kit.line(at(-.78, .34), at(-.36, .34), 1.7 + .16 * Math.sin(t * .6), "lit") +
    kit.line(at(-.2, .34), at(.78, .34), .8) +
    kit.line(at(-.78, 0), at(.78, 0), .8) +
    kit.line(at(-.78, -.34), at(.3, -.34), .8);
}"""

PAGE = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Invariant: __TITLE__</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,100..900&display=swap">
<style>
/* The tokens and the light of tools/architecture.py: one lit plate, glass in a dark room, porcelain on a grey table
   with a cast shadow in place of the glow. The light comes from the upper left in both. The cue is lit (blue). */
:root {
  color-scheme: light dark;
  --paper: #eceef0; --sheet: #fbfcfc; --ink: #101820; --mute: #56636d; --faint: #606c76; --rule: #d3d9de;
  --blue: #1f43d6; --red: #c41e34;
  --glass-hi: #ffffff; --glass: #f9fafb; --glass-lo: #dfe4e8;
  --rim-a: rgba(16, 24, 32, .28); --rim-b: rgba(16, 24, 32, .58); --rim-c: rgba(16, 24, 32, .9);
  --glow: 0; --shadow: 1; --spec: 0; --bloom: .4; --dot-off: .22; --chip: rgba(31, 67, 214, .1);
}
@media (prefers-color-scheme: dark) {
  :root {
    --paper: #080c11; --sheet: #111922; --ink: #e9eff3; --mute: #93a1ad; --faint: #788590; --rule: #1c2630;
    --blue: #8fb1ff; --red: #ff6b7c;
    --glass-hi: #34485e; --glass: #152029; --glass-lo: #090e14;
    --rim-a: rgba(255, 255, 255, .92); --rim-b: rgba(255, 255, 255, .1); --rim-c: rgba(143, 177, 255, .45);
    --glow: 1; --shadow: 0; --spec: 1; --bloom: 1; --dot-off: .26; --chip: rgba(143, 177, 255, .16);
  }
}
* { box-sizing: border-box; }
html { background: var(--paper); }
body {
  margin: 0; color: var(--ink); background: var(--paper);
  font: 400 15px/1.5 "Archivo", ui-sans-serif, -apple-system, "Segoe UI", system-ui, sans-serif;
  font-variant-numeric: tabular-nums; -webkit-font-smoothing: antialiased;
}
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: left; }
a { color: inherit; }
:focus-visible { outline: 2px solid var(--blue); outline-offset: 3px; border-radius: 3px; }
.page {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(320px, 27vw); grid-template-rows: auto minmax(0, 1fr);
  gap: 0; height: 100vh; min-height: 620px; max-width: 1840px; margin: 0 auto; padding: 20px 40px 28px;
}
.top { grid-column: 1 / -1; display: flex; align-items: center; gap: 26px; font-size: 13px; padding-bottom: 16px; border-bottom: 1px solid var(--rule); }
.name { font-weight: 740; font-stretch: 122%; font-size: 15px; letter-spacing: .02em; margin: 0 6px 0 0; }
.top a { color: var(--mute); text-decoration: none; white-space: nowrap; transition: color .15s ease; }
.top a:hover { color: var(--ink); }
.top a[aria-current] { color: var(--ink); font-weight: 600; }

/* The picture: one plate with the start of an answer, the dots and the count, and the one switch */
.stage { min-height: 0; min-width: 0; display: flex; flex-direction: column; justify-content: center; padding: 8px 40px 0 0; }
svg { width: 100%; max-height: calc(100vh - 200px); display: block; overflow: visible; cursor: default; user-select: none; -webkit-user-select: none; }
svg:focus:not(:focus-visible) { outline: none; }
svg text { font-family: inherit; fill: var(--ink); font-stretch: 104%; }
svg * { pointer-events: none; }
.atmo { opacity: var(--glow); }
.shade { fill: var(--ink); opacity: calc(var(--shadow) * .17); }
.spec { opacity: var(--spec); }
.back { fill: var(--glass-lo); stroke: var(--rim-b); stroke-width: 1; }
.plate { fill: url(#body) var(--sheet); stroke: url(#rim) var(--ink); stroke-width: 1.7; }
.strip { fill: var(--glass-lo); fill-opacity: .55; stroke: var(--rim-b); stroke-width: 1; }
.slab { fill: var(--mute) !important; font-weight: 520; }
.chip { fill: var(--chip); stroke: var(--blue); stroke-width: 1.4; }
.chipglow { fill: var(--blue); opacity: calc(var(--bloom) * .22); }
.chipt { fill: var(--blue) !important; font-weight: 680; }
.cont { fill: var(--ink) !important; font-weight: 420; }
.cont.p { fill: var(--mute) !important; }
.mk { fill: none; stroke: var(--ink); stroke-linecap: round; }
.flip { fill: none; stroke: var(--blue); stroke-linecap: round; }
.flipg { opacity: calc(var(--bloom) * .26 + .06); }
.kd2 { fill: var(--blue); opacity: calc(var(--bloom) * .26 + .06); }
.sel { fill: none; stroke: var(--ink); stroke-width: 2; }
.big { font-weight: 330; letter-spacing: -.035em; font-stretch: 100%; }
.lab { fill: var(--mute) !important; font-weight: 520; }
.lab2 { fill: var(--ink) !important; font-weight: 600; }
.track { stroke: var(--faint); stroke-width: 1.4; opacity: .5; }
.fill { stroke: var(--ink); stroke-linecap: round; }
.fe { fill: var(--ink); }
.ref { stroke-width: 2; stroke-linecap: round; stroke: var(--ink); }
.ref.r { stroke: var(--blue); }
.reftext { font-weight: 600; text-anchor: middle; }
.reftext.r { fill: var(--blue) !important; }
.reftext.b { fill: var(--mute) !important; }
.kd0 { fill: var(--ink); opacity: .92; } .kd1 { fill: var(--ink); opacity: var(--dot-off); }
.switch { display: inline-flex; align-self: center; margin-top: 18px; border: 1px solid var(--faint); border-radius: 999px; padding: 3px; }
.switch button { padding: 8px 20px; border-radius: 999px; font-weight: 600; font-size: 15px; white-space: nowrap; transition: background .15s ease, color .15s ease; }
.switch button:hover { color: var(--blue); }
.switch button[aria-pressed="true"] { background: var(--ink); color: var(--paper); }
.hint { align-self: center; margin: 10px 0 0; font-size: 13px; color: var(--mute); text-align: center; }

@keyframes draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes fade { from { opacity: 0; } }
.enter .draw { stroke-dasharray: 1; animation: draw 1.1s cubic-bezier(.6, 0, .2, 1) both; }
.enter .atmo, .enter .shade, .enter .spec, .enter .back { animation: fade 1.3s .15s both; }
.enter .bar, .enter .marks, .enter .read, .enter .key { animation: fade .7s .5s both; }

/* The words */
.side {
  min-width: 0; min-height: 0; overflow-y: auto; scrollbar-width: none;
  padding: clamp(20px, 7vh, 96px) 0 0 40px; border-left: 1px solid var(--rule);
}
.problem { margin: 0; color: var(--mute); font-size: clamp(16px, 1.25vw, 20px); line-height: 1.3; max-width: 26ch; }
.say { margin: 14px 0 0; font-size: clamp(25px, 2.15vw, 40px); line-height: 1.14; font-weight: 300; font-stretch: 102%; letter-spacing: -.016em; max-width: 17ch; }
.say b { font-weight: 620; white-space: nowrap; }
.say .nw { white-space: nowrap; }
.pane { margin-top: clamp(22px, 4vh, 44px); }
.more { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--rule); }
.more button { display: flex; width: 100%; justify-content: space-between; align-items: baseline; padding: 12px 0; border-bottom: 1px solid var(--rule); font-size: 17px; font-weight: 520; transition: color .15s ease; }
.more button span { color: var(--faint); font-size: 20px; line-height: 1; }
.more button:hover { color: var(--blue); }
.dhead { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding-bottom: 12px; border-bottom: 1px solid var(--ink); }
.dhead h2 { margin: 0; font-size: 17px; font-weight: 660; font-stretch: 114%; letter-spacing: .008em; }
.close { font-size: 13px; color: var(--mute); }
.close:hover { color: var(--ink); }
.lead { margin: 18px 0 0; font-size: clamp(17px, 1.3vw, 21px); line-height: 1.36; font-weight: 380; max-width: 30ch; overflow-wrap: anywhere; }
.lead.q { font-size: 15.5px; line-height: 1.45; color: var(--ink); max-width: 44ch; }
.facts { list-style: none; margin: 18px 0 0; padding: 0; font-size: 14.5px; color: var(--mute); max-width: 40ch; overflow-wrap: anywhere; }
.facts li { padding: 8px 0; border-top: 1px solid var(--rule); }
.facts b { color: var(--ink); font-weight: 600; }
.verdict { color: var(--ink); font-weight: 640; }
.txt { margin: 14px 0 0; padding-top: 10px; border-top: 1px solid var(--rule); font-size: 13.5px; line-height: 1.5; max-width: 44ch; overflow-wrap: anywhere; white-space: pre-wrap; }
.txt .cap { margin: 0 0 6px; color: var(--faint); font-size: 12.5px; white-space: normal; }
.txt p { margin: 0; color: var(--mute); }
.txt .c { color: var(--blue); font-weight: 650; background: var(--chip); border-radius: 3px; }
.steps { display: flex; justify-content: space-between; margin-top: 14px; font-size: 13px; color: var(--mute); }
.steps button:hover { color: var(--ink); }
@media (max-width: 900px) {
  /* On a phone the order is: the problem, the finding, the picture, the depth. */
  .page { display: flex; flex-direction: column; height: auto; min-height: 0; padding: 16px 16px 40px; }
  .top { gap: 13px; padding-bottom: 12px; flex-wrap: wrap; }
  .name { font-stretch: 112%; margin-right: 0; }
  .side { display: contents; }
  .problem { order: 1; margin-top: 20px; max-width: none; }
  .say { order: 2; max-width: 22ch; }
  .stage { order: 3; margin-top: 22px; padding: 0; display: block; }
  .pane { order: 4; margin-top: 22px; }
  svg { max-height: none; }
  .switch { display: flex; margin-top: 16px; }
  .switch button { flex: 1; text-align: center; padding: 10px 6px; }
}
@media (prefers-reduced-motion: reduce) {
  .enter * { animation: none !important; }
  .switch button, .more button, .top a { transition: none; }
}
</style>
</head>
<body>
<div class="page">
  <header class="top">
    <h1 class="name">Invariant</h1>
    <a href="/">Board</a>
    <a href="/architecture">Design</a>
    <a href="/proof">Proof</a>
    <a href="/findings" aria-current="page">Findings</a>
  </header>
  <div class="stage" id="stage">
    <svg id="svg" role="img" tabindex="0"></svg>
    <div class="switch" id="switch" role="group" aria-label="The start of the answer">
      <button data-state="0" aria-pressed="false">Base</button>
      <button data-state="1" aria-pressed="false">Base + cue</button>
    </div>
    <p class="hint">Click a dot to see its problem and how both answers begin.</p>
  </div>
  <div class="side">
    <p class="problem" id="problem"></p>
    <p class="say" id="say"></p>
    <div class="pane" id="pane" aria-live="polite"></div>
  </div>
</div>
<script>
const C = __CONFIG__, D = C.data, $ = id => document.getElementById(id);
const still = matchMedia("(prefers-reduced-motion: reduce)"), narrow = matchMedia("(max-width: 900px)");
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const RAD = Math.PI / 180, f = n => n.toFixed(1), mix = (a, b, q) => a + (b - a) * q;
const ease = p => p < .5 ? 2 * p * p : 1 - (-2 * p + 2) ** 2 / 2, clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const pct = v => `${v.toFixed(1)} %`;

/* A problem is one row of PROBLEMS. o: its outcome without and with the cue (r right, w wrong, c cut off). The dots keep
   one place each: right in both runs first, then right only with the cue, right only without it, right in neither, so
   switching the cue on lights one block of dots and darkens a few. */
const PR = C.problems.map(([i, q, gold, o0, o1, a0, a1, s0, s1]) => ({ i, q, gold, o: [o0, o1], a: [a0, a1], s: [s0, s1] }));
const N = D.n, LEVELS = 8, GROUP = p => p.o[0] === "r" ? (p.o[1] === "r" ? 0 : 2) : (p.o[1] === "r" ? 1 : 3);
const ORDER = PR.map((p, k) => k).sort((a, b) => GROUP(PR[a]) - GROUP(PR[b]) || PR[a].i - PR[b].i);
const SLOT = []; ORDER.forEach((k, s) => { SLOT[k] = s; });
const right = (p, st) => p.o[st] === "r";
const count = st => PR.reduce((n, p) => n + right(p, st), 0);
const CUE = ["line!", "↵", "↵", "Okay"];  // the cue " line!\n\nOkay" as it reads: a word, two line breaks, a word
const S = { st: 1, open: null, intro: false, t1: null, g: null, el: {}, shown: {}, t: 0, last: 0, q: 1, q0: 1, t0: -1e9,
  from: [], to: [], n0: 0, n1: 0, pos: [], ex: null };

/* Geometry in a small 3D space around the plate's centre (x right, y down, z toward the viewer). */
function geo() {
  return narrow.matches
    ? { w: 480, h: 1040, cx: 240, cy: 520, D: 2000, a: [6, 8, 474, 1032], r: 22, deep: 30, blur: 12,
        labY: 50, strip: [22, 66, 458, 124], tx: 38, ty: 103, tf: 20, chipH: 34,
        bigX: 30, bigY: 248, fb: 104, labX: 32, lab1: 284, lab2: 312, tr: [36, 444], trY: 380, refUp: 352, refDn: 414,
        cols: 20, pitch: 20.6, gx: 44, gy: 486, d: [3.6, 10.4], keyY: 1000, kx: [44, 140, 236], fs: 18 }
    : { w: 1000, h: 620, cx: 500, cy: 310, D: 2200, a: [20, 14, 980, 606], r: 30, deep: 40, blur: 16,
        labY: 60, strip: [52, 76, 948, 132], tx: 72, ty: 113, tf: 24, chipH: 36,
        bigX: 572, bigY: 324, fb: 118, labX: 576, lab1: 362, lab2: 392, tr: [576, 920], trY: 480, refUp: 456, refDn: 512,
        cols: 25, pitch: 18, gx: 72, gy: 196, d: [3.4, 9.4], keyY: 570, kx: [72, 168, 266], fs: 17 };
}
const V = { c1: 1, s1: 0, c2: 1, s2: 0, px: 0, py: 0, tx: 0, ty: 0 };
function aim(yaw, pitch) { V.c1 = Math.cos(yaw * RAD); V.s1 = Math.sin(yaw * RAD); V.c2 = Math.cos(pitch * RAD); V.s2 = Math.sin(pitch * RAD); }
function proj(g, x, y, z) {
  const X = x - g.cx, Y = y - g.cy, x1 = X * V.c1 + z * V.s1, z1 = z * V.c1 - X * V.s1;
  const y1 = Y * V.c2 - z1 * V.s2, k = g.D / (g.D - (z1 * V.c2 + Y * V.s2));
  return [g.cx + x1 * k, g.cy + y1 * k];
}
function rounded(g, [x0, y0, x1, y1], r, z) {
  const p = [], corner = (cx, cy, a0) => { for (let i = 0; i <= 6; i++) p.push(proj(g, cx + r * Math.cos((a0 + 15 * i) * RAD), cy + r * Math.sin((a0 + 15 * i) * RAD), z)); };
  corner(x1 - r, y0 + r, -90); corner(x1 - r, y1 - r, 0); corner(x0 + r, y1 - r, 90); corner(x0 + r, y0 + r, 180);
  return "M" + p.map(q => f(q[0]) + " " + f(q[1])).join("L") + "Z";
}

function build() {
  const g = S.g = geo(), svg = $("svg"), [ax0, ay0, ax1, ay1] = g.a, aw = ax1 - ax0, ah = ay1 - ay0, [sx0, sy0, sx1, sy1] = g.strip;
  const stop = (at, color, alpha) => `<stop offset="${at}" style="stop-color:${color}${alpha == null ? "" : ";stop-opacity:" + alpha}"/>`;
  const mk = [...Array(LEVELS)].map((_, l) => { const q = l / (LEVELS - 1);
    return `<path class="mk" id="m${l}" stroke-width="${f(mix(g.d[0], g.d[1], q))}" style="opacity:calc(var(--dot-off) + ${(q * .92).toFixed(3)} - var(--dot-off) * ${q.toFixed(3)})"/>`; }).join("");
  const X = v => mix(g.tr[0], g.tr[1], v / N), lv = (v, up, cls, text) =>
    `<line class="ref ${cls}" x1="${f(X(v))}" y1="${f(g.trY - (up ? 13 : 4))}" x2="${f(X(v))}" y2="${f(g.trY + (up ? 4 : 13))}"/>` +
    `<text class="reftext ${cls}" x="${f(X(v))}" y="${f(up ? g.refUp : g.refDn)}" font-size="${g.fs}">${esc(text)}</text>`;
  svg.setAttribute("viewBox", `0 0 ${g.w} ${g.h}`);
  svg.innerHTML = "<defs>" +
    `<radialGradient id="body" cx=".3" cy=".22" r=".95">${stop(0, "var(--glass-hi)")}${stop(.46, "var(--glass)")}${stop(1, "var(--glass-lo)")}</radialGradient>` +
    `<linearGradient id="rim" x1=".06" y1=".04" x2=".94" y2=".96">${stop(0, "var(--rim-a)")}${stop(.56, "var(--rim-b)")}${stop(1, "var(--rim-c)")}</linearGradient>` +
    `<radialGradient id="atmo">${stop(.5, "var(--blue)", .2)}${stop(.72, "var(--blue)", .06)}${stop(1, "var(--blue)", 0)}</radialGradient>` +
    `<radialGradient id="spec">${stop(0, "#fff", .2)}${stop(1, "#fff", 0)}</radialGradient>` +
    `<linearGradient id="fadeg" gradientUnits="userSpaceOnUse" x1="${sx0}" y1="0" x2="${sx1}" y2="0">${stop(0, "#fff", 1)}${stop(.72, "#fff", 1)}${stop(1, "#fff", 0)}</linearGradient>` +
    `<mask id="fade" maskUnits="userSpaceOnUse" x="${sx0 - 40}" y="${sy0 - 40}" width="${sx1 - sx0 + 80}" height="${sy1 - sy0 + 80}"><rect x="${sx0 - 40}" y="${sy0 - 40}" width="${sx1 - sx0 + 52}" height="${sy1 - sy0 + 80}" fill="url(#fadeg)"/></mask>` +
    `<filter id="soft" x="-20%" y="-20%" width="140%" height="150%"><feGaussianBlur stdDeviation="${g.blur}"/></filter></defs>` +
    `<ellipse class="atmo" cx="${g.cx}" cy="${g.cy}" rx="${f(aw * .8)}" ry="${f(ah * .9)}" fill="url(#atmo)"/>` +
    `<rect class="shade" x="${f(ax0 + aw * .012)}" y="${f(ay0 + ah * .04)}" width="${aw}" height="${ah}" rx="${g.r}" filter="url(#soft)"/>` +
    `<path class="back" id="back"/><path class="plate draw" id="plate" pathLength="1"/>` +
    `<ellipse class="spec" cx="${f(ax0 + aw * .3)}" cy="${f(ay0 + ah * .24)}" rx="${f(aw * .3)}" ry="${f(ah * .2)}" transform="rotate(-14 ${f(ax0 + aw * .3)} ${f(ay0 + ah * .24)})" fill="url(#spec)"/>` +
    `<g class="bar"><text class="slab" id="slab" font-size="${g.fs}"></text><path class="strip" id="strip"/>` +
    `<g id="txt" mask="url(#fade)"><text class="cont p" id="c0" font-size="${g.tf}"></text><text class="cont" id="c1" font-size="${g.tf}"></text>` +
    `<g id="chips">${CUE.map((w, k) => `<rect class="chipglow" id="cg${k}" rx="9"/><rect class="chip" id="cr${k}" rx="7"/><text class="chipt" id="ct${k}" font-size="${g.tf}">${w}</text>`).join("")}</g></g></g>` +
    `<text class="lab" id="gcap" font-size="${g.fs}">${N} problems, one dot each</text>` +
    `<g class="marks"><g class="flipg"><path class="flip" id="flip"/></g>${mk}<circle class="sel" id="sel" r="0"/></g>` +
    `<g class="key"><circle class="kd0" id="kd0" r="${g.d[1] / 2}"/><text class="lab" id="kt0" font-size="${g.fs}">Right</text>` +
    `<circle class="kd1" id="kd1" r="${g.d[0] / 2 + .4}"/><text class="lab" id="kt1" font-size="${g.fs}">Wrong</text>` +
    `<circle class="kd2" id="kd2" r="${g.d[1] * .95}"/><circle class="kd0" id="kd3" r="${g.d[1] / 2}"/><text class="lab" id="kt2" font-size="${g.fs}">Changed by the cue</text></g>` +
    `<g class="read"><text class="big" id="big" font-size="${g.fb}"></text>` +
    `<text class="lab2" id="lab1" font-size="${g.fs + 2}"></text><text class="lab" id="lab2" font-size="${g.fs}">The cue turns ${D.flips.up} problems right, ${D.flips.down} wrong.</text>` +
    `<line class="track" x1="${g.tr[0]}" y1="${g.trY}" x2="${g.tr[1]}" y2="${g.trY}"/>` +
    lv(D.states[0].right, false, "b", `Base ${D.states[0].right}`) + lv(D.states[1].right, true, "", `Base + cue ${D.states[1].right}`) +
    lv(D.rl_level, false, "r", `RL ${D.rl_level}`) +
    `<line class="fill" id="fill" x1="${g.tr[0]}" y1="${g.trY}" y2="${g.trY}" stroke-width="4.5"/><circle class="fe" id="fe" cy="${g.trY}" r="6.5"/></g>`;
  S.el = {}; S.shown = {}; S.ex = null;
  svg.querySelectorAll("[id]").forEach(e => { S.el[e.id] = e; });
}

/* The answer at the top: the open problem's, or the example's. Without the cue it is the plain answer's first words; with
   it, the cue's three tokens stand lit at the start and the answer goes on after them. */
function example() {
  const k = S.open && S.open[0] === "p" ? PR.findIndex(p => "p" + p.i === S.open) : -1;
  return k >= 0 ? PR[k] : PR.find(p => p.i === D.example);
}
const flat = s => s.replace(/\s+/g, " ").trim();
function fitStrip() {
  const g = S.g, E = S.el, p = example();
  if (S.ex === p.i) return;
  S.ex = p.i;
  E.slab.textContent = `MATH-500, problem ${p.i}: the start of the answer`;
  E.c0.textContent = p.s[0].trim() ? flat(p.s[0]) : "(empty: the answer ended at its first token)";
  E.c1.textContent = flat(p.s[1]);
  let x = g.tx;
  CUE.forEach((w, k) => {
    const t = E["ct" + k], wd = t.getComputedTextLength(), pad = 9;
    t.setAttribute("x", f(x + pad)); t.setAttribute("y", f(g.ty));
    for (const r of [E["cr" + k], E["cg" + k]]) {
      const grow = r === E["cg" + k] ? 4 : 0;
      r.setAttribute("x", f(x - grow)); r.setAttribute("y", f(g.ty - g.chipH * .68 - grow));
      r.setAttribute("width", f(wd + 2 * pad + 2 * grow)); r.setAttribute("height", f(g.chipH + 2 * grow));
    }
    x += wd + 2 * pad + 6;
  });
  S.cueW = x - g.tx;
  E.c0.setAttribute("x", g.tx); E.c0.setAttribute("y", g.ty);
}

function dotAt(k, now) {
  const a = S.from[k], b = S.to[k];
  if (a === b) return [b, 0];
  const p = clamp((now - S.t0 - SLOT[k]) / 520, 0, 1), e = ease(p);
  return [mix(a, b, e), Math.sin(Math.PI * p)];
}
function place(t, now) {
  const g = S.g, E = S.el, at = (el, q, dy) => { el.setAttribute("x", f(q[0])); el.setAttribute("y", f(q[1] + (dy || 0))); };
  const text = (id, v) => { if (S.shown[id] !== v) E[id].textContent = S.shown[id] = v; };
  E.back.setAttribute("d", rounded(g, g.a, g.r, -g.deep));
  E.plate.setAttribute("d", rounded(g, g.a, g.r, 0));
  E.strip.setAttribute("d", rounded(g, g.strip, 12, 8));
  at(E.slab, proj(g, g.strip[0], g.labY, 6));
  fitStrip();

  // The cue slides in from the left and the plain start gives way to the cued one; q runs from 0 (no cue) to 1 (cue).
  const q = mix(S.q0, S.st, ease(clamp((now - S.t0) / 700, 0, 1)));
  S.q = q;
  const shift = proj(g, g.tx, g.ty, 10)[0] - g.tx, lift = proj(g, g.tx, g.ty, 10)[1] - g.ty;
  E.txt.setAttribute("transform", `translate(${f(shift)} ${f(lift)})`);
  E.chips.setAttribute("opacity", q.toFixed(2)); E.chips.setAttribute("transform", `translate(${f((q - 1) * 26)} 0)`);
  E.c0.setAttribute("opacity", Math.max(0, 1 - 2 * q).toFixed(2));
  E.c1.setAttribute("opacity", Math.max(0, 2 * q - 1).toFixed(2));
  E.c1.setAttribute("x", f(g.tx + S.cueW + 2)); E.c1.setAttribute("y", g.ty);
  for (let k = 0; k < CUE.length; k++) E["cg" + k].setAttribute("opacity", (.6 + .4 * Math.sin(t * 1.1 + k)).toFixed(2));

  // The dots, batched by look into LEVELS paths. A dot that changes with the cue lifts toward the viewer on its way,
  // and the dots whose outcome the cue changes keep a faint lit halo.
  const paths = Array(LEVELS).fill("");
  let halo = "";
  for (let k = 0; k < PR.length; k++) {
    const s = SLOT[k], col = s % g.cols, row = (s - col) / g.cols, [v, hop] = dotAt(k, now);
    const p = proj(g, g.gx + col * g.pitch, g.gy + row * g.pitch, 6 + 30 * hop);
    S.pos[k] = p;
    paths[Math.round(v * (LEVELS - 1))] += "M" + f(p[0]) + " " + f(p[1]) + "h0";
    if (PR[k].o[0] === "r" ? PR[k].o[1] !== "r" : PR[k].o[1] === "r") halo += "M" + f(p[0]) + " " + f(p[1]) + "h0";
  }
  paths.forEach((d, l) => E["m" + l].setAttribute("d", d));
  E.flip.setAttribute("d", halo); E.flip.setAttribute("stroke-width", f(g.d[1] * 1.9));
  E.flip.setAttribute("opacity", q.toFixed(2));
  const sel = S.open && S.open[0] === "p" ? PR.findIndex(p => "p" + p.i === S.open) : -1;
  if (sel >= 0) { E.sel.setAttribute("cx", f(S.pos[sel][0])); E.sel.setAttribute("cy", f(S.pos[sel][1])); E.sel.setAttribute("r", f(g.pitch * .55)); }
  else E.sel.setAttribute("r", "0");
  [0, 1, 2].forEach(k => {
    const p = proj(g, g.kx[k], g.keyY, 4);
    for (const d of k === 2 ? [E.kd2, E.kd3] : [E["kd" + k]]) { d.setAttribute("cx", f(p[0])); d.setAttribute("cy", f(p[1])); }
    at(E["kt" + k], [p[0] + g.fs * (k === 2 ? 1.1 : .8), p[1]], g.fs * .35);
  });
  at(E.gcap, proj(g, g.gx - g.d[1] / 2, g.gy - 26, 6));

  // The count: it counts with the dots and stops within 0.9 s.
  const e = ease(clamp((now - S.t0) / 900, 0, 1)), n = mix(S.n0, S.n1, e), X = v => mix(g.tr[0], g.tr[1], v / N);
  text("big", pct(100 * n / N));
  text("lab1", `${Math.round(n)} of ${N} right · ${D.states[S.st].name}, T 1.0`);
  at(E.big, [g.bigX, g.bigY]); at(E.lab1, [g.labX, g.lab1]); at(E.lab2, [g.labX, g.lab2]);
  E.fill.setAttribute("x2", f(X(n))); E.fe.setAttribute("cx", f(X(n)));
}

/* Always on: the plate sways by a few degrees and leans toward the mouse. About 30 frames a second. With reduced motion
   the page shows one still frame per state. */
function frame(now) {
  requestAnimationFrame(frame);
  if (still.matches || now - S.last < 30) return;
  S.last = now;
  if (S.intro && now - (S.t1 ??= now) > 900) setState(1);  // the entrance is timed from the first frame shown, not from load
  const t = S.t = now / 1000;
  V.px += (V.tx - V.px) * .1; V.py += (V.ty - V.py) * .1;
  aim(4 * Math.sin(t * .13) + 3.5 * V.px, 2 * Math.sin(t * .09) - 2 * V.py);
  place(t, now);
}
function setState(st, opts = {}) {
  const now = performance.now(), quick = still.matches || opts.instant;
  const cur = PR.map((p, k) => quick ? 0 : dotAt(k, now)[0]), e = ease(clamp((now - S.t0) / 900, 0, 1));
  const n = mix(S.n0, S.n1, e), q = S.q;
  S.intro = false; S.st = st;
  S.to = PR.map(p => right(p, st) ? 1 : 0);
  S.from = quick ? S.to.slice() : cur;
  S.n1 = count(st); S.n0 = quick ? S.n1 : n; S.q0 = quick ? st : q;
  S.t0 = quick ? -1e9 : now;
  $("switch").querySelectorAll("button").forEach((b, k) => b.setAttribute("aria-pressed", k === st));
  $("svg").setAttribute("aria-label", `${N} MATH-500 problems, one dot each. ${D.states[st].say} ${S.n1} of ${N} right at T 1.0; ` +
    `Base ${D.states[0].right}, Base + cue ${D.states[1].right}, RL ${D.rl_level}. Enter opens a problem.`);
  if (still.matches) { aim(0, 0); place(0, now); }
}

/* The side column: the five panels, or one problem with both answers. */
function said(p, st) {
  const x = p.o[st], a = p.a[st];
  return x === "r" ? `answered <span data-math>${esc(a)}</span>: right`
    : x === "c" ? `was cut off at ${D.cap.toLocaleString("en-US")} tokens: wrong`
    : a ? `answered <span data-math>${esc(a)}</span>: wrong` : "gave no answer the grader could read: wrong";
}
function problemPane(k) {
  const p = PR[k], start0 = p.s[0].trim() ? esc(p.s[0]) : "(empty: the answer ended at its first token)";
  return `<div class="dhead"><h2>MATH-500, problem ${p.i}</h2><button class="close" data-open="">Close</button></div>` +
    `<p class="lead q" data-math>${esc(p.q)}</p>` +
    `<ul class="facts"><li><b>Base</b>, T 1.0, <span class="verdict">${said(p, 0)}</span>.</li>` +
    `<li><b>Base + cue</b>, T 1.0, <span class="verdict">${said(p, 1)}</span>.</li>` +
    `<li>The reference answer is <span data-math>${esc(p.gold)}</span>.</li></ul>` +
    `<div class="txt"><p class="cap">How the answer begins, Base (first ${p.s[0].length} characters)</p><p data-math>${start0} …</p></div>` +
    `<div class="txt"><p class="cap">How the answer begins, Base + cue (the cue is lit)</p><p data-math>${D.cue_text.trim().split(/(\s+)/).map(w => /\S/.test(w) ? `<span class="c">${esc(w)}</span>` : w).join("")}${esc(p.s[1])} …</p></div>` +
    `<div class="steps"><button data-step="-1">‹ Previous problem</button><button data-step="1">Next problem ›</button></div>`;
}
function pane() {
  const p = C.panels.find(p => p[0] === S.open), k = S.open && S.open[0] === "p" ? PR.findIndex(q => "p" + q.i === S.open) : -1;
  $("pane").innerHTML = k >= 0 ? problemPane(k) : p
    ? `<div class="dhead"><h2>${esc(p[1])}</h2><button class="close" data-open="">Close</button></div><p class="lead">${esc(p[2])}</p>` +
      `<ul class="facts">${p[3].map(x => `<li>${esc(x).replace(/\[\[([^|\]]+)\|([^\]]+)\]\]/g, '<a href="$2">$1</a>')}</li>`).join("")}</ul>`
    : `<ul class="more">${C.panels.map(p => `<li><button data-open="${p[0]}">${esc(p[1])}<span aria-hidden="true">›</span></button></li>`).join("")}</ul>`;
  if (still.matches) place(0, performance.now());
}
/* The state and what is open are one value in the address: #<base|cue>, then /<panel> or /p<problem>. */
const KEYS = D.states.map(s => s.key);
function address(push) {
  const parts = [S.st === 1 ? "" : KEYS[S.st], S.open || ""].filter(Boolean);
  const url = parts.length ? "#" + parts.join("/") : location.pathname;
  push ? history.pushState(null, "", url) : history.replaceState(null, "", url);
}
function fromHash(first) {
  const parts = decodeURIComponent(location.hash.slice(1)).split("/"), k = KEYS.indexOf(parts[0]), st = k < 0 ? 1 : k;
  const rest = parts.find(x => C.panels.some(p => p[0] === x) || PR.some(p => "p" + p.i === x));
  if (first === true || st !== S.st) setState(st, { instant: first === true });
  // A first visit with no state in the address starts without the cue and switches it on once the page is shown.
  if (first === true && !location.hash && !still.matches) { setState(0, { instant: true }); S.intro = true; }
  S.open = rest || null;
  pane();
}
function open(key) {
  const was = S.open;
  S.open = key || null;
  address(true);
  pane();
  const to = $("pane").querySelector(key ? ".close" : `[data-open="${was}"]`);
  if (to) to.focus({ preventScroll: true });
  else if (!key) $("svg").focus({ preventScroll: true });
}

const svg = $("svg");
function svgPoint(e) { const m = svg.getScreenCTM().inverse(); return [m.a * e.clientX + m.c * e.clientY + m.e, m.b * e.clientX + m.d * e.clientY + m.f]; }
function nearest([x, y]) {
  let best = -1, bd = (S.g.pitch * .7) ** 2;
  S.pos.forEach((q, k) => { const d = (q[0] - x) ** 2 + (q[1] - y) ** 2; if (d < bd) { bd = d; best = k; } });
  return best;
}
svg.addEventListener("pointermove", e => { if (e.pointerType === "mouse") svg.style.cursor = nearest(svgPoint(e)) >= 0 ? "pointer" : "default"; });
svg.addEventListener("click", e => {
  const k = nearest(svgPoint(e));
  if (k >= 0) { open("p" + PR[k].i); if (narrow.matches) $("pane").scrollIntoView({ behavior: still.matches ? "auto" : "smooth", block: "start" }); }
});
document.addEventListener("click", e => {
  const b = e.target.closest("[data-state]"), o = e.target.closest("[data-open]"), s = e.target.closest("[data-step]");
  if (b) { setState(Number(b.dataset.state)); address(false); }
  if (o) open(o.dataset.open);
  if (s) {
    const k = PR.findIndex(p => "p" + p.i === S.open), slot = (SLOT[k] + Number(s.dataset.step) + PR.length) % PR.length;
    open("p" + PR[ORDER[slot]].i);
    $("pane").querySelector(`[data-step="${s.dataset.step}"]`).focus({ preventScroll: true });
  }
});
document.addEventListener("keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === "Escape" && S.open) open("");
  if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
    const st = e.key === "ArrowRight" ? 1 : 0;
    if (st !== S.st) { setState(st); address(false); }
    if (document.activeElement && document.activeElement.closest("#switch")) $("switch").children[S.st].focus();
  }
  if (e.key === "Enter" && document.activeElement === svg) {
    e.preventDefault();  // Enter opens the first problem the cue turns right; it must not also press the Close it focuses
    open("p" + PR[ORDER.find(k => GROUP(PR[k]) === 1)].i);
  }
});
addEventListener("hashchange", fromHash);
addEventListener("popstate", fromHash);
narrow.addEventListener("change", () => { build(); place(S.t, performance.now()); });
still.addEventListener("change", () => { if (still.matches) { setState(S.st, { instant: true }); aim(0, 0); place(0, performance.now()); } });
document.fonts.ready.then(() => { S.ex = null; place(S.t, performance.now()); });  // measure the cue again in the loaded typeface
const stage = $("stage");
stage.addEventListener("pointermove", e => {
  if (e.pointerType !== "mouse" || still.matches) return;
  const b = stage.getBoundingClientRect();
  V.tx = 2 * (e.clientX - b.left) / b.width - 1; V.ty = 2 * (e.clientY - b.top) / b.height - 1;
});
stage.addEventListener("pointerleave", () => { V.tx = V.ty = 0; });

$("problem").textContent = C.problem;
$("say").innerHTML = esc(C.line).replace(/(?<![\w-])(\d+(?:[.,]\d+)*(?: ?%)?)/g, "<b>$1</b>").replace(/MATH-500/g, '<span class="nw">MATH-500</span>');
build();
aim(0, 0);
fromHash(true);
place(0, performance.now());
if (!still.matches) {
  svg.classList.add("enter");
  setTimeout(() => svg.classList.remove("enter"), 2200);
}
requestAnimationFrame(frame);
</script>
</body>
</html>
"""

PAGE = PAGE.replace("__TITLE__", TITLE).replace("__CONFIG__", json.dumps({
    "problem": PROBLEM, "line": LINE, "panels": PANELS, "problems": PROBLEMS,
    "data": {k: DATA[k] for k in ("n", "cap", "flips", "states", "rl_level", "cue_text", "example")}}))

if __name__ == "__main__":  # run from the repository root
    problems = _build()
    if sys.argv[1:] == ["--write"]:
        src = open(__file__).read()
        start, end = src.index("PROBLEMS = "), src.index("\n\n", src.index("PROBLEMS = "))
        src = src[:start] + "PROBLEMS = [\n" + "".join("    " + json.dumps(r, ensure_ascii=False) + ",\n" for r in problems) + "]" + src[end:]
        open(__file__, "w").write(src)
        sys.exit(f"wrote {len(problems)} problems")
    assert PROBLEMS == problems, "PROBLEMS differ from the artifacts: run with --write"
    cells = json.load(open(DATA["artifact"]))["cells"]
    for key, cell in (("plain", "base_plain_1.0"), ("cue", "base_opener_1.0")):
        c = cells[cell]
        assert (DATA[key]["right"], DATA[key]["right_v1"], DATA[key]["nothing_extracted"], DATA[key]["cap_hits"]) == \
            (c["right_v3"], c["right_v1"], c["nothing_extracted_v3"], c["cap_hits"]), key
    assert DATA["rl_first"]["right"] == cells["rl_1.0"]["right_v3"] and DATA["plain_t06"]["right"] == cells["base_plain_0.6"]["right_v3"]
    assert (sum(p[3] == "r" for p in PROBLEMS), sum(p[4] == "r" for p in PROBLEMS)) == (PLAIN, CUE)
    assert (sum(p[4] == "r" and p[3] != "r" for p in PROBLEMS), sum(p[3] == "r" and p[4] != "r" for p in PROBLEMS)) == (DATA["flips"]["up"], DATA["flips"]["down"])
    assert json.load(open(DATA["cue_artifact"]))["prefill_text"] == DATA["cue_text"]
    assert (SHARE, SHARE_BEST) == (78, 63)
    print("DATA and PROBLEMS match", DATA["artifact"], "and", DATA["rows"])
